import pytest
from mailmerge.render import render


def test_render_fills_fields():
    assert render("Hi {name}", {"name": "Ann"}) == "Hi Ann"


@pytest.mark.xfail(strict=True, reason="ticket 021")
def test_missing_field_raises():
    with pytest.raises(KeyError, match="name"):
        render("Hi {name}", {})

from collections import defaultdict


def render(template: str, fields: dict[str, str]) -> str:
    return template.format_map(defaultdict(str, fields))


def render_all(template: str, rows: list[dict[str, str]]) -> list[str]:
    return [render(template, row) for row in rows]
